"""Product-specific web copy; features checked against catalog evidence and policies."""
from copy import deepcopy
from seo_draft_content import PAGES as PILOTS
PAGES=deepcopy(PILOTS)

def add(slug,title,description,intro,sections,faq,shots):
 PAGES[slug]=dict(title=title,h1=title,description=description,intro=intro,sections=sections,faq=faq,screenshots=shots)

add('local-lore','Local history and landmarks near you',
'Discover nearby history, landmarks and local legends with Local Lore for Android. Browse maps, explore another town, and follow the original sources.',
'Local Lore is an Android app for discovering the stories around a place. Browse local history, landmarks, legends, wildlife notes, and film locations in a list or on a map. It is for curious residents as well as travelers: you can explore a familiar neighborhood or look up somewhere you plan to visit.',[
('Start with a place, then follow your curiosity','Choose nearby discovery or search for another town, address, or postal code. The app retrieves information about the area and lets you narrow the results by theme. Read a short entry to decide what interests you, then open its linked sources for more detail. You can save favorites on your device to revisit places that caught your attention.'),
('Use it before a trip or during a walk','A map helps you understand where discoveries are located, while the list makes it easier to browse several stories without moving around the map. Search another neighborhood before leaving home, or use nearby discovery during a break. An entry is a starting point for learning about a place; check its source and public access before planning a visit.'),
('Connection and location choices','Internet access is needed to retrieve new discoveries and map tiles. Nearby discovery sends coordinates directly to public information providers, not to a TripperDeeLabs location server. You can search a place instead of granting current-location access. The app does not request background location or continue discovering after it closes. There are no ads or TripperDeeLabs accounts; the privacy policy explains the external services involved.')],[
('Can I search somewhere other than my current location?','Yes. Enter a town, address, or postal code to explore another area. This also gives you a way to use discovery without granting current-location access.'),
('Are the stories sourced?','Entries link to their sources so you can investigate further. Local legends and historical records are different kinds of material; read the linked context before treating a story as established fact.'),
('Does Local Lore work entirely offline?','No. New discoveries, maps, and external source pages need internet access. Favorites and a recently retrieved area cache are stored locally, but they are not a complete offline travel guide.'),
('How can I report a missing place?','Use Send feedback in the app or email feedback@tripperdeelabs.com. Include the place and a useful source link. Suggestions are reviewed rather than published automatically.')],[(1,'Local Lore dark theme with nearby discoveries and theme filters'),(2,'Local Lore light theme showing history results for San Francisco'),(4,'Local Lore map with discovery markers around the San Francisco Bay area')])

add('roboball','Offline arcade basketball for Android',
'Play RoboBall offline on Android. Time your release, aim at moving hoops, practice trick shots, and save your stars and basketball scores on your phone.',
'RoboBall is an arcade basketball game for Android built around timing your shot. Watch the power meter, choose when to release, and see the ball react to the hoop and its surroundings. It suits players who want short shooting challenges, a place to practice, and progress they can keep on their own phone.',[
('Learn the release, then adjust your aim','Start with untimed practice or guided practice to get a feel for the meter. A successful shot depends on timing and aim, while the ball interacts with the rim, backboard, and obstacles. Once the basic release feels familiar, moving baskets, wind, and changes in gravity give you different conditions to work with. Replaying a court lets you try a different approach.'),
('Explore courts and keep improving','The game moves beyond a single basketball cabinet. Its settings include city stages, rooftops, railways, underwater courts, planetary gravity challenges, and Kenai Salmon Shot. Review your result after a run and replay to earn more stars. Scores, progression, and trophies are saved on the device, making the challenge about your own attempts rather than an online leaderboard.'),
('Set up a comfortable game','Options cover audio, haptics, contrast, the heads-up display, motion, and the aiming guide. Use these controls to make the shooting feedback easier to follow on your phone. The game pauses when interrupted. It runs offline without ads, a subscription, or an account, so playing does not depend on a signal or a sign-in service.')],[
('Can I play on a flight without Wi-Fi?','Yes. RoboBall runs offline after installation. Scores, stars, and trophies are saved locally on the phone.'),
('Is there a practice mode?','Yes. Untimed practice and guided practice help you learn the release before you work through timed challenges and changing court conditions.'),
('Does progress transfer through an online account?','No account is required and progression is local. Do not rely on a cloud profile to restore your scores when changing phones or removing app data.'),
('Does the game contain ads or subscriptions?','No. RoboBall is a one-time purchase with no ads or subscriptions. The current price and device availability are shown on Google Play.')],[(1,'RoboBall practice court with basketball, aim controls, and power meter'),(2,'RoboBall instructions explaining the power meter and release timing'),(4,'RoboBall timed basketball run showing the countdown and target score')])

add('moto-thrash','Offline motocross racing and track building',
'Race 24 tracks in Moto Thrash for Android. Balance your bike, time your boost, attempt bus jumps, and build custom courses that stay on your device.',
'Moto Thrash is a retro motocross game for Android with racing, bike balance, and a local course builder. Race computer opponents across 24 tracks in four cups, or step away from the race schedule to design a course. It is for players who enjoy learning jumps and experimenting with an arcade dirt bike.',[
('Balance the bike and manage your boost','Use the on-screen directional pad to change lanes and control bike balance. Keeping the bike level in the air helps you line up a landing. Wheelies and front-wheel balances give you more ways to ride, but pushing too far costs stability. Boost adds another decision: watch engine heat and choose when the extra speed will help you through the track.'),
('Build a course you can ride','The editor provides six local save slots. Place ramps, bumps, mud, oil, boost pads, and jump hazards, then ride the result. Water, rivers, cars, buses, and other scenery or hazards let you try different arrangements. Custom tracks are stored on the device; the editor is a way to experiment on your own phone, without an online publishing or sharing service.'),
('Try a different kind of jump','Stunt Show lets you set up a bus-jumping attempt with a chosen ramp and run-up speed. Work toward a clean landing and compare the result with your personal best. Racing and custom courses also work offline. There are no ads, in-app purchases, or accounts, and progress stays on the device rather than in a developer-operated cloud save.')],[
('Can I play Moto Thrash without internet?','Yes. The racing, course builder, and Stunt Show work offline after installation. No account or online session is needed to play.'),
('Can I share tracks or race other people online?','No. Moto Thrash is single-player. You race computer opponents, and the six custom-course slots are local to your device.'),
('How many tracks are included?','The game includes 24 tracks across four cups. The course builder and Stunt Show provide separate ways to experiment with jumps and layouts.'),
('What happens to my custom courses if I clear storage?','Courses and progress are local app data. Clearing storage or uninstalling can remove them; the game does not provide a cloud-save account.')],[(2,'Moto Thrash racers approaching a dirt ramp with race position and heat indicators'),(3,'Moto Thrash track builder with ramps, hazards, and local save-slot controls'),(4,'Stunt Show setup for bus count, ramp size, and run-up speed')])

add('captain-quack','Offline arcade space shooter for Android',
'Guide Captain Quack through aliens, asteroids and gravity wells. Play an offline Android space shooter with touch controls, pickups, and local scores.',
'Captain Quack is an arcade space shooter starring a duck in a spaceship. Steer through alien formations, avoid asteroids, and keep firing as each run gets harder. The game is for players looking for a straightforward touch-controlled arcade challenge, with scores and career ranks saved on their own Android device.',[
('Steer, shoot, and watch the whole screen','A touch joystick controls movement, and a separate fire button handles shooting. You need to make room for your ship while aiming at the enemies ahead. Alien formations, asteroids, and gravity wells change what you need to respond to. Clearing an entire formation earns a bonus, so choosing where to move can matter as much as holding the fire button.'),
('Use pickups during a run','Shield, rapid-fire, wide-shot, and extra-life pickups can help you keep a run going. Their value depends on the situation you are facing: a different weapon or a little protection may change how you approach a crowded screen. Pause when you need a break, and use the separate music and sound controls to suit where you are playing.'),
('Keep a personal score to beat','The game records a local top five and career ranks. These give you a record to return to without requiring an account or an online leaderboard. Captain Quack runs offline after installation and contains no ads or in-app purchases. Scores and settings remain on the device. Clearing the app’s storage or uninstalling removes that local progress, so it is worth knowing where your records live.')],[
('Does Captain Quack need Wi-Fi?','No. The game works offline after installation. You do not need an account or a connection to play a run and save a score.'),
('How do I control the ship?','Use the touch joystick to steer and the dedicated fire button to shoot. Watch for pickups while avoiding asteroids, alien formations, and gravity wells.'),
('Can I pause and change the sound?','Yes. Pause and resume your run, and use the music and sound settings when you want a quieter session.'),
('Are scores stored online?','No. The top-five scores and career ranks stay on your device. Removing app data or uninstalling removes local progress; there is no account-based score recovery.')],[(2,'Captain Quack firing at alien formations with touch joystick and fire button'),(3,'Captain Quack ship beside a gravity well during a space-shooter run'),(4,'Captain Quack facing a large alien enemy with score and level indicators')])

add('dive-watch','Analog dive-style watch face for Wear OS',
'Customize Dive Watch for Wear OS with steel, red or green themes, analog hands, a date window, and a battery gauge built into the left dial marker.',
'Dive Watch is an analog watch face for Wear OS, with a dive-inspired dial and everyday watch information. It combines sculpted hands, luminous markers, and a date window with a battery indicator built into the left marker. It is for people who prefer a traditional dial while keeping a useful data field on the watch.',[
('Choose the dial that suits you','Classic steel, Red night, and Green lume are included. Customize the hands, choose a wave-textured or pure-black dial, and decide whether to show seconds or an additional digital time readout. The Classic steel theme has accent-color options. A separate always-on layout shows clear digital time and the date when your watch’s display settings allow it.'),
('Read battery and your chosen complication','The wide marker at nine o’clock is the battery gauge. Its fill shrinks as the charge falls, while the border stays visible. Tap it to open battery status for an exact percentage. The lower circle shows steps by default, but you can choose another compatible complication. That data comes from your watch or selected provider; Dive Watch does not independently record activity.'),
('Install on the watch, then customize','Install from Google Play to a compatible Wear OS watch. Touch and hold your current face, choose Add watch face, and select Dive Watch. Open Customize to change the theme and lower data source. There is no separate phone companion, account, subscription, advertising, or analytics in the face. The face has no network permission; a selected data provider can have its own connection needs and privacy practices.')],[
('Which watches can use Dive Watch?','It requires Wear OS 5 or newer. It is a watch face for Wear OS, not an Android phone app, Garmin face, or Apple Watch face.'),
('Does it measure depth or make my watch waterproof?','No. The design is decorative. It adds no water resistance and provides no dive-computer functions; follow your watch manufacturer’s operating limits.'),
('Are all three themes included?','Yes. Classic steel, Red night, and Green lume are included in the purchase. There is no subscription or separate theme purchase.'),
('Why might a complication be empty?','Data availability depends on the watch and selected provider. Check the provider’s setup and permissions in watch settings. Some providers may require internet access to update.')],[(1,'Dive Watch Classic steel dial with analog hands, date, and lower steps field'),(3,'Dive Watch Red night theme with red luminous hands and markers'),(4,'Dive Watch Green lume theme with green hands and dial markers')])

add('amelia-navigator','Aviation watch face for Wear OS',
'Amelia Navigator brings a navy aviation dial, brass details and an hourly aircraft animation to Wear OS, with digital time and available watch readings.',
'Amelia Navigator is an aviation-style watch face for Wear OS. A navy dial, brass details, compass-style markings, and digital time draw on historical flight instruments. It is for people who enjoy that visual style and want everyday watch readings alongside an aircraft animation, without installing a separate phone interface.',[
('A flight-inspired dial for everyday timekeeping','The round layout combines large digital time with day, date, and seconds. Select a 12-hour or 24-hour display to match how you read time. Navigator Navy and Night Instrument dial styles provide different looks, with Brushed Brass or Monochrome accents around the ring. The quieter ambient display pares the face back for the watch’s always-on mode.'),
('Watch the aircraft approach','At the top of each hour, a twin-engine aircraft approaches and settles beneath the north marker. Tap the face to replay the approach when you want to see it again. The animation is a visual detail of the face, not a live aircraft tracker. Its flight-instrument styling does not turn the decorative ring into a magnetic compass or navigation system.'),
('Use the readings your watch supplies','Battery, steps, heart rate, and weather information come from Wear OS and its providers. What appears depends on the device, sensors, permissions, and configured services. The face does not send those readings to TripperDeeLabs. There is no account, advertising, or analytics in Amelia Navigator. A provider used by the watch can have its own network requirements and privacy practices, especially for fresh weather information.')],[
('What operating system does it need?','Amelia Navigator requires Wear OS 5 or newer. This listing is for the watch face, not a phone app or a face for Garmin or Apple Watch.'),
('How do I change its appearance?','Touch and hold the watch face to open the Wear OS picker and customization controls. Choose a dial style and ring accent, then use the supported time-format options.'),
('Is the compass ring a navigation tool?','No. The compass-style ring is decorative. Do not use the face to determine a bearing, plan a route, or replace a navigation instrument.'),
('Why are some health or weather readings missing?','The face displays available Wear OS data. Check the watch sensors, provider settings, and permissions; the face itself does not supply a separate health or weather service.')],[(1,'Amelia Navigator navy dial with 12-hour time, brass ring, and data fields'),(2,'Amelia Navigator minimal ambient display with digital time and date'),(4,'Amelia Navigator aircraft animation crossing the lower part of the dial')])

add('summit-line','Mountain watch face for Wear OS',
'See digital time over mountain scenery with Summit Line for Wear OS. Choose landscapes, accents, a step-goal ring, and compatible data complications.',
'Summit Line is a scenic digital watch face for Wear OS. Mountain backgrounds sit behind large time digits and everyday watch readings. It is for people who want an outdoor-inspired face for daily wear, with a choice of scenery and a step-goal ring rather than a full hiking or navigation app.',[
('Choose scenery and readable time','Pick Sunrise Hike, Whitney Trail, Alpine, Night Trail, or Pure Black. Automatic scenery changes with fixed morning, daytime, and night periods based on local time; it does not calculate sunrise or sunset at your location. Choose an accent color, show or hide seconds and the moon phase, and select a supported time format. A minimal ambient display keeps time visible on compatible watch settings.'),
('Set a goal for the step ring','The outer ring compares your watch’s native step count with a goal selected in Summit Line. Goals range from 5,000 to 20,000 steps, and the ring can be turned off. The number and ring use the same native count, but the selected goal does not synchronize with your health app. Summit Line displays available activity information rather than recording a workout itself.'),
('Customize data without a studio account','Compatible complication slots can show information from installed providers. Available weather, heart rate, and other readings depend on the watch and those services. Summit Line has no ads, account, subscription, or developer-operated data service. On supported Wear OS 6 setups, the system photo-selection flow can also provide a personal background; the face does not upload that photo to TripperDeeLabs.')],[
('Does Summit Line record hikes or show GPS routes?','No. The mountain artwork is decorative. The face has no built-in GPS navigation, hike recorder, compass service, or altitude service.'),
('Which Wear OS version is required?','The face requires Wear OS 5 or newer with Watch Face Format support. Personal-photo customization needs Wear OS 6 and a supported watch and paired-phone system flow.'),
('Can I use my health app’s step goal?','The ring uses native watch steps and a goal chosen inside Summit Line. It does not synchronize the goal from a separate health app.'),
('Why does a data field show a dash?','A reading may be unavailable from the watch or chosen provider. Check the provider’s installation, settings, and permissions. Some updates, such as weather, may need a connection.')],[(1,'Summit Line mountain scenery with digital time and lower data fields'),(2,'Summit Line minimal always-on time display'),(4,'Summit Line detailed mountain dial with moon phase, steps, and battery')])

add('kenai-fishing-report','Kenai fishing reports on your Wear OS watch',
'View Kenai sockeye counts, Soldotna water temperature and Cape Kasilof tides on Wear OS with Kenai Fishing Report and its separate data companion.',
'Kenai Fishing Report is a Wear OS watch face that places public fishing-report information beside the time. With the separate Kenai Report Data companion installed, it can show a sockeye count, river temperature, and the next predicted tide. It is designed for people who follow Kenai Peninsula reports and want a quick view on their watch.',[
('Install the face and its data companion','Install Kenai Report Data on the same watch, then select Kenai Fishing Report as the watch face. Assign the Kenai complication providers if they are not selected automatically. The companion retrieves the reports; the face arranges them on the dial. You do not need a phone app or studio account, but the watch needs internet access for fresh information.'),
('Understand what each reading represents','The fish field shows the latest reported Kenai late-run sockeye count and season total from ADF&G. The water temperature is for the USGS Soldotna station. The tide field uses NOAA Cape Kasilof predictions in Alaska time. Tap for details and source links, and read the count date and stale-report label. A predicted coastal tide is not a measured Kenai River level.'),
('Make the display yours','Choose river scenery or a black backdrop, then select an accent color and time format. The face includes date, battery, and moon phase, with a minimal always-on view. You can use native steps and heart-rate readings in place of the river and tide row. Available readings depend on the watch and providers. Neither the face nor companion requires an account or includes developer-operated tracking.')],[
('Why do I need Kenai Report Data?','It supplies the fishing-report complications. Install it separately on the same watch; the watch face alone does not download the river, fish, and tide reports.'),
('How current are the reports?','Updates are requested about every 30 minutes, but Wear OS can defer them and sources can be delayed. Older data is marked stale; off-season counts may remain unchanged for a long time.'),
('Does a fish count mean fishing is open?','No. Reports are unofficial context, not permission to fish or a catch forecast. Check current official regulations, emergency orders, and local conditions.'),
('Which devices are supported?','Wear OS 5 or newer with Watch Face Format 2 is required. The face is for Wear OS watches, not phones, Garmin, or Apple Watch.')],[(1,'Kenai Fishing Report dial showing sockeye count, time, river temperature, and tide'),(2,'Kenai Fishing Report minimal always-on time display'),(4,'Detailed Kenai watch dial with a stale count date and source labels')])

add('launch-vector','Rocket launch countdown watch face for Wear OS',
'Follow a rocket launch countdown on Wear OS with Launch Vector. Add its free data companion for schedule updates alongside time and watch readings.',
'Launch Vector is a free Wear OS watch face with a rocket launch countdown. It combines time and everyday watch readings with launch status and an animated rocket. It is for space enthusiasts who want to glance at a scheduled launch from their wrist while still using the watch for ordinary timekeeping.',[
('Add the launch-data companion','Install the free Launch Vector Data Provider companion so the face can refresh its schedule. The face and companion perform different jobs: one displays the countdown, while the other retrieves launch information. Fresh schedules require internet access. The companion keeps the latest successful schedule and refresh times on the watch, but a saved report cannot account for a schedule change while disconnected.'),
('Read time and the countdown together','The face supports 12-hour and 24-hour time, launch status, an interactive display, and a quieter ambient mode. Its rocket animation is part of the visual design. Weather, battery, steps, and heart-rate fields display information supplied through Wear OS and compatible providers. Available data and update behavior depend on the watch, its settings, and the services selected for those fields.'),
('Know where network requests go','Neither the watch face nor the data companion requests your device location. Launch-site locations refer to the rockets. The companion contacts the TripperDeeLabs launch service over HTTPS; that service and its hosting provider can process normal connection details such as IP addresses and request times. It does not receive your health readings, an advertising identifier, or an account profile. The apps contain no advertising or analytics SDKs.')],[
('Is Launch Vector free?','The watch face and Launch Vector Data Provider companion are free. Check Google Play for device compatibility and regional availability before installing.'),
('Does the countdown update without internet?','Fresh launch schedules need a connection through the companion. Cached information can become outdated, so confirm an important launch with the launch operator before making plans.'),
('Does this app track my location?','No. Neither app requests device location access. The launch service receives ordinary network metadata needed to deliver and operate its schedule service, as described in the privacy policy.'),
('Is it an official SpaceX app?','No. Launch Vector is independent and is not affiliated with or endorsed by SpaceX. Its launch-inspired design does not imply access to an operator’s internal schedule.')],[(1,'Launch Vector dial with rocket countdown, weather, and battery over an Earth horizon'),(3,'Launch Vector ambient mode with subdued time and countdown'),(4,'Launch Vector 24-hour display showing scheduled launch details')])

add('private-eyes','Offline encrypted photo vault for Android',
'Keep photos and files in an encrypted Android vault with Private Eyes. Capture privately, manage imported originals, and understand local recovery limits.',
'Private Eyes is an encrypted photo and file vault for Android. It stores selected files on your phone and includes a camera for photos and short silent videos captured directly into the vault. It is for people who want deliberate control over private copies without a developer account or an online storage service.',[
('Import a copy, then manage the original','Choose files with Android’s file picker, review the import result, and open important copies to check them. Importing does not automatically hide or delete the source from Gallery, Downloads, or a cloud library. Optional original removal depends on the source provider and Android confirmation. Other copies can remain elsewhere, so review them separately instead of assuming one import protects every version.'),
('Keep access and exports deliberate','AES-256-GCM encryption protects file contents, filenames, and stored thumbnails. The vault uses your pattern and device authentication, and locks when you leave the app or turn off the screen. Search and media filters help you browse stored items. Exports create readable copies outside the vault; choose a destination carefully and check what metadata remains. Direct private capture avoids making a Gallery original first.'),
('Plan for local storage and recovery limits','Private Eyes has no internet permission, ads, analytics, account, or cloud service. Your vault is not uploaded to TripperDeeLabs, and the developer holds no recovery key. Losing your pattern, phone, or device keys can mean losing the contents permanently. Do not keep the only copy of irreplaceable files in the vault. Its protection does not promise forensic invisibility or independent security certification.')],[
('What Android version is required?','Private Eyes requires Android 13 or newer and a device screen lock. Camera controls and media previews depend on your device and the file format.'),
('Does importing remove a Gallery photo?','No. Importing creates a protected copy. Removal of the original is a separate, optional action, and other local or cloud copies may remain.'),
('Can I recover my vault on another phone?','There is no portable encrypted backup, recovery service, or pattern reset. If the original phone still works, export and verify important files before changing devices.'),
('Can I take videos inside the vault?','Yes. The built-in camera captures short silent videos directly into the vault. Videos are limited to two minutes and subject to storage and device limits.')],[(1,'Private Eyes Case Files screen with encrypted daily folders and import controls'),(2,'Private Eyes vault grid containing sample documents and illustrations'),(4,'Private Eyes welcome screen asking for device-security verification')])

add('wonder-cascade','Match-3 puzzles with time to think',
'Explore Wonder Cascade, a match-3 puzzle game in development. Plan gem swaps, combine powers, and try finite-board challenges without a countdown timer.',
'Wonder Cascade is a match-3 puzzle game in development for Android. Swap neighboring gems, clear gold, and use combinations of powers to reach the board’s goals. It is designed for players who enjoy thinking through a sequence of moves. The screenshots below show the development build, not a publicly released Google Play version.',[
('Learn a move, then plan a combination','The opening lessons introduce matching three, creating a Lightning, and combining powers. Different match shapes create different effects: a line of four makes Lightning, a square makes a Glider, an L or T makes a Nova, and a line of five makes a Prism. Plan move lets you inspect the first wave of a chosen move before committing it.'),
('Switch from cascades to finite puzzles','Regular journey boards introduce objectives such as gold, ice, suns, shields, and directional crystal relays. Every fifth fresh journey level is a Strategy Stop, with a finite board and no replacement gems. These challenges ask you to consider how later moves depend on the first. Free Undo lets you test an idea rather than starting over after every experiment.'),
('A development preview with clear limits','The current build includes journey levels, expert puzzles, Mind puzzles, and daily challenges. There are no countdown timers or lives; settings include separate music and sound controls and Reduced Motion. Saved progress lets you return to a puzzle. Android advertising and purchase integration is still being tested, so this page does not promise an ad-free Android release or a final price. Read the app privacy policy for the current integration details.')],[
('Can I download it from Google Play?','A public Google Play listing is not currently available at the known app URL. This page is a preview; a verified download link will be added when the app is released.'),
('What makes Strategy Stops different?','They use finite gems with no replacements. Planning the order of swaps matters because one clear changes what remains for the next move.'),
('Is there a timer?','The current development game has no countdown timers or lives. You can pause, return to saved puzzles, and use the available sound and motion settings.'),
('Can I watch a puzzle being solved?','The development build includes Computer Run and solution viewing. Spectator runs keep personal records separate. Features may change before public release.')],[(1,'Wonder Cascade development tutorial showing a blue-gem swap to match three'),(2,'Wonder Cascade development Strategy Stop with six moves and finite gems')])

add('moments','Personal photo watch face for Wear OS',
'Preview Moments, a photo watch face for Wear OS 6. See a curved photo panel, digital time, customizable data fields, and clear on-device privacy choices.',
'Moments is a photo watch face project for Wear OS 6, pairing a curved image panel with digital time and everyday data fields. It is intended for people who want a personal picture on their wrist without losing a readable time display. Public Google Play availability has not been confirmed, so the images here show a development build.',[
('A picture beside the time','The design keeps the photo to one side of a large digital clock, with a centered weekday and date. Soft Colors, Silver, and Champagne themes change the information styling. The current build includes an optional minute ring, a battery percentage and fill, and four customizable complications. In always-on mode, a simpler layout leaves out the photo.'),
('Use the watch platform to choose an image','Personal-photo selection is designed around the supported paired-phone and Wear OS system flow. That platform handles selection, cropping, transfer, and storage. Moments displays the selected image without sending it to TripperDeeLabs. Included sample images are illustrative, AI-generated artwork; the lake shown in these screenshots is a sample, not a real user’s personal photograph.'),
('Understand the development status','The current project targets Wear OS 6 or newer. Emulator captures have been used to review its layout and editor options. Personal-photo transfer with a paired phone, persistence, and physical-watch provider behavior still need real-device validation. This preview is not a promise that every watch and phone pairing has been tested. No public price or download button is shown until a release listing is available.')],[
('Can I install Moments from Google Play now?','The known public listing is currently unavailable. This page describes the project and its development screenshots, not an available purchase.'),
('Does Moments upload my photos?','No. The face has no network permission or developer upload service. The watch platform and paired-phone software handle photo selection and transfer under their own privacy policies.'),
('Can I choose the data fields?','The current build supports four customizable complications. Available readings and tap actions depend on the watch and providers; missing data can appear as dashes.'),
('Is there a separate Moments phone app?','No separate TripperDeeLabs phone app is planned for this flow. Photo selection uses the supported watch manufacturer or Google companion software. Compatibility still needs validation before release.')],[(1,'Moments development watch face with Soft Colors theme and sample alpine-lake photo'),(2,'Moments development watch face with Silver theme, digital time, and sample lake photo')])

add('alaska-gold-run','Offline Alaska runner game for Android',
'Explore snowy trails, railway tunnels and frozen lakes in Alaska Gold Run, an offline Android runner. See real gameplay and its Google Play review status.',
'Alaska Gold Run is a three-lane Android runner set among snowy trails, railway tunnels, ice caves, and frozen lakes. Swipe to change lanes, jump over hazards, and slide under obstacles while collecting gold. It is for players who enjoy learning a route, reacting to changing terrain, and returning to beat their own score.',[
('Submitted to Google Play','Alaska Gold Run has been submitted to Google Play. Its Play Console status is “Changes in review,” last updated October 24, 2026. Review is still pending, so there is no public download available here yet. This page will link to the public listing when it becomes available. The Android package is com.tripperdeelabs.alaskagoldrun.'),
('Run, ski, and skate through Alaska-inspired scenery','The routes include a Whittier Tunnel-inspired railway, an ice cave, downhill skiing, and skating across frozen terrain. Outdoor night scenes feature an aurora. Watch for trains, wildlife crossing your path, and swooping eagles while choosing a clear lane. Spring Boots and timed double-score pickups add options during a run, and each environment gives you a different set of hazards to learn.'),
('Earn rewards through play','Collect gold and work through missions to earn gear and outfit choices. Daily gifts and the Lucky Pan provide in-game rewards. The submitted release is designed as a pay-once offline game without advertising or in-app purchases. At base camp, adjust swipe sensitivity, graphics, sound, and vibration to make the controls and presentation comfortable on your phone.'),
('Keep your progress on your device','Gameplay does not need an account or an internet connection after installation. Progress and settings stay locally on the device; the game has no analytics or online account service. Clearing app storage or uninstalling can remove your saved progress. The screenshots below are real desktop gameplay captures from release preparation, so the final Android display may differ.')],[
('Is Alaska Gold Run available to download?','It has been submitted to Google Play and is marked “Changes in review,” last updated October 24, 2026. A public download link will be added when the listing is available.'),
('Can I play without Wi-Fi?','Yes. The submitted release is designed for offline play after installation, with progress and settings stored on your device.'),
('Are there ads or purchases for gold?','The submitted release has no ads or in-app purchases. Gold, outfits, and gear are earned through gameplay. The intended model is a one-time purchase.'),
('Will an account restore my progress on another phone?','There is no game account or cloud-save service. Progress stays locally, and clearing storage or uninstalling can remove it.')],[(1,'Alaska Gold Run downhill skiing route with snowy obstacles beneath an aurora'),(2,'Alaska Gold Run railway tunnel with three lanes, gold pickups, and a runner'),(3,'Alaska Gold Run frozen-lake skating route with ice hazards and gold pickups')])
